selection-change-does-not-reorder-surviv.body:
const firstSelection = value.first.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, `first-${index}`));
const secondSelection = value.second.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, `second-${index}`));
const commands = value.commands.map((tag: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => makeCommand(String(index), tag === 'global' ? 'global' : [tag]));
const firstItems = contextMenuItems(firstSelection, commands, []);
const secondItems = contextMenuItems(secondSelection, commands, []);
const firstIds = firstItems.map((item: { id: unknown }) => item.id);
const secondIds = secondItems.map((item: { id: unknown }) => item.id);
const applicable = (selection: ReadonlyArray<{ kind: 'node' | 'edge' | 'group' | 'annotation' }>, tag: 'global' | 'node' | 'edge' | 'group' | 'annotation'): boolean => tag === 'global' || (selection.length > 0 && selection.some((element: { kind: 'node' | 'edge' | 'group' | 'annotation' }) => element.kind === tag));
expect(firstIds).toEqual(value.commands.map((_: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => String(index)).filter((_: string, index: number) => applicable(firstSelection, value.commands[index])));
expect(secondIds).toEqual(value.commands.map((_: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => String(index)).filter((_: string, index: number) => applicable(secondSelection, value.commands[index])));

