eligible-command.body:
const command = {
  id: 'copy',
  label: value.label,
  appliesTo: value.appliesTo,
  run: () => undefined,
};
const keymap = value.hasBinding
  ? [{ command: 'copy', chord: { key: 'x', meta: false, shift: false } }]
  : [];
const items = commandPaletteItems([command], keymap);
expect(items).toEqual([
  {
    key: 'command:copy',
    label: value.label,
    detail: value.hasBinding ? 'X' : '',
    action: { kind: 'command', command: 'copy' },
  },
]);

